import type { SubtitleTrack } from './types.js';

/**
 * Sous-titres déjà présents chez Internet Archive.
 *
 * Mesuré le 11/11/2026 : Internet Archive génère lui-même des sous-titres automatiques (reconnaissance
 * vocale) sous forme de fichiers `<nom>.asr.srt`, `<nom>.asr.vtt` ou `<nom>.autogenerated.vtt`.
 * Présents sur 70 % des longs métrages, 80 % des actualités Universal, 100 % des films Prelinger testés.
 * Des déposants ajoutent aussi leurs propres fichiers, parfois avec un code de langue (`film.fr.srt`).
 */

const SUBTITLE_FILE = /\.(vtt|srt)$/i;
const AUTO_MARK = /(?:^|[._-])(?:asr|autogenerated|auto|autosub)(?:[._-]|$)/i;
const LANG_SUFFIX = /[._-]([a-z]{2})$/i;

/** Codes de langue plausibles (ISO 639-1) : évite de prendre « hd » ou « de » d'un mot pour une langue. */
const KNOWN_LANGS = new Set([
  'ar', 'bg', 'ca', 'cs', 'da', 'de', 'el', 'en', 'es', 'fa', 'fi', 'fr', 'he', 'hi', 'hu', 'it', 'ja', 'ko', 'nl', 'no', 'pl', 'pt', 'ro', 'ru', 'sv', 'tr', 'uk', 'vi', 'zh',
]);

/** « film_512kb.asr.srt » → { base: « film_512kb.asr », lang: undefined, auto: true }. */
export function describeSubtitleFile(name: string): { base: string; lang?: string; auto: boolean } | null {
  if (!SUBTITLE_FILE.test(name)) return null;
  const file = name.split('/').pop() ?? name;
  const base = file.replace(SUBTITLE_FILE, '');
  const auto = AUTO_MARK.test(base);
  const stripped = base.replace(AUTO_MARK, '');
  const m = LANG_SUFFIX.exec(stripped);
  const lang = m?.[1] && KNOWN_LANGS.has(m[1].toLowerCase()) ? m[1].toLowerCase() : undefined;
  return { base, ...(lang ? { lang } : {}), auto };
}

export interface SubtitleFile {
  name?: string;
  size?: string | number;
  private?: string | boolean;
}

const MAX_TRACKS = 6;

/**
 * Choisit les pistes à proposer : une par (langue, auto), en préférant WebVTT à SRT, en ignorant les
 * fichiers vides. `downloadUrl` construit l'adresse complète d'un fichier de l'objet.
 */
export function pickSubtitles(files: SubtitleFile[], downloadUrl: (name: string) => string, itemLang?: string): SubtitleTrack[] {
  const best = new Map<string, { track: SubtitleTrack; vtt: boolean; size: number }>();
  for (const f of files) {
    if (!f.name || f.private === true || f.private === 'true') continue;
    const d = describeSubtitleFile(f.name);
    if (!d) continue;
    const size = Number(f.size ?? 0);
    if (Number.isFinite(size) && size > 0 && size < 40) continue; // fichier vide ou quasi vide
    const isVtt = /\.vtt$/i.test(f.name);
    const lang = d.lang ?? (d.auto ? itemLang : undefined);
    const key = `${lang ?? '?'}|${d.auto ? 'auto' : 'manual'}`;
    const prev = best.get(key);
    // WebVTT d'abord ; à format égal, le fichier le plus gros (souvent le plus complet).
    if (!prev || (isVtt && !prev.vtt) || (isVtt === prev.vtt && size > prev.size)) {
      best.set(key, { track: { url: downloadUrl(f.name), ...(lang ? { lang } : {}), auto: d.auto }, vtt: isVtt, size });
    }
  }
  return [...best.values()]
    .map((b) => b.track)
    .sort((a, b) => Number(a.auto) - Number(b.auto)) // les sous-titres « humains » avant les automatiques
    .slice(0, MAX_TRACKS);
}

/** SRT → WebVTT : en-tête, virgule des millisecondes remplacée par un point. Un WebVTT est renvoyé tel quel. */
export function toVtt(text: string): string {
  const clean = text.replace(/^﻿/, '').replace(/\r\n?/g, '\n');
  if (/^WEBVTT/.test(clean)) return clean;
  const body = clean
    .split('\n')
    .map((line) => (line.includes('-->') ? line.replace(/(\d{1,2}:\d{2}:\d{2}),(\d{1,3})/g, '$1.$2') : line))
    .join('\n');
  return `WEBVTT\n\n${body.trim()}\n`;
}

/** Hôtes autorisés pour le relais de sous-titres : fichiers d'Internet Archive uniquement. */
export function isArchiveDownloadUrl(raw: string): boolean {
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    return false;
  }
  return (
    url.protocol === 'https:' &&
    url.port === '' &&
    !url.username &&
    !url.password &&
    (url.hostname === 'archive.org' || url.hostname.endsWith('.archive.org')) &&
    (url.pathname.startsWith('/download/') || /^\/\d+\/items\//.test(url.pathname)) &&
    SUBTITLE_FILE.test(url.pathname)
  );
}

/** Langue parlée renseignée par Internet Archive (« English », « eng », « fre »…) → code ISO 639-1. */
const LANG_NAMES: Record<string, string> = {
  english: 'en', eng: 'en', en: 'en',
  french: 'fr', fre: 'fr', fra: 'fr', fr: 'fr', 'français': 'fr', francais: 'fr',
  german: 'de', ger: 'de', deu: 'de', de: 'de',
  spanish: 'es', spa: 'es', es: 'es',
  italian: 'it', ita: 'it', it: 'it',
  russian: 'ru', rus: 'ru', ru: 'ru',
  japanese: 'ja', jpn: 'ja', ja: 'ja',
  chinese: 'zh', chi: 'zh', zho: 'zh', zh: 'zh',
  portuguese: 'pt', por: 'pt', pt: 'pt',
  dutch: 'nl', dut: 'nl', nld: 'nl', nl: 'nl',
  swedish: 'sv', swe: 'sv', sv: 'sv',
  polish: 'pl', pol: 'pl', pl: 'pl',
  arabic: 'ar', ara: 'ar', ar: 'ar',
};

export function languageCode(raw: unknown): string | undefined {
  const first = (Array.isArray(raw) ? raw[0] : raw) as unknown;
  if (typeof first !== 'string') return undefined;
  return LANG_NAMES[first.trim().toLowerCase()];
}
